using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;

namespace ResearchAgent;

/// <summary>
/// Provides web search capability for the research agent.
/// Uses the Bing Web Search REST API when an API key is configured;
/// otherwise returns a placeholder result so the agent loop can still be demonstrated.
/// </summary>
public sealed class WebSearchTool
{
    private readonly HttpClient _httpClient;
    private readonly string? _bingApiKey;

    public WebSearchTool(HttpClient httpClient)
    {
        _httpClient = httpClient;
        _bingApiKey = Environment.GetEnvironmentVariable("BING_API_KEY");
    }

    [Description("Searches the web for information on a given query and returns a list of relevant results with titles, snippets, and URLs.")]
    public async Task<string> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5)
    {
        if (maxResults is < 1 or > 10)
        {
            maxResults = 5;
        }

        if (!string.IsNullOrWhiteSpace(_bingApiKey))
        {
            return await SearchWithBingAsync(query, maxResults);
        }

        return GeneratePlaceholderResults(query, maxResults);
    }

    private async Task<string> SearchWithBingAsync(string query, int maxResults)
    {
        var requestUri = $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count={maxResults}";

        using var request = new HttpRequestMessage(HttpMethod.Get, requestUri);
        request.Headers.Add("Ocp-Apim-Subscription-Key", _bingApiKey);

        using var response = await _httpClient.SendAsync(request);
        response.EnsureSuccessStatusCode();

        using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
        var results = new List<object>();

        if (doc.RootElement.TryGetProperty("webPages", out var webPages) &&
            webPages.TryGetProperty("value", out var values))
        {
            foreach (var item in values.EnumerateArray().Take(maxResults))
            {
                results.Add(new
                {
                    title = item.GetProperty("name").GetString(),
                    snippet = item.GetProperty("snippet").GetString(),
                    url = item.GetProperty("url").GetString(),
                });
            }
        }

        return results.Count > 0
            ? JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true })
            : "No results found.";
    }

    private static string GeneratePlaceholderResults(string query, int maxResults)
    {
        // Simulated results so the agent loop works without a real API key.
        var results = new List<object>();
        var topics = new[]
        {
            ("Overview", "A comprehensive overview covering the fundamental concepts, history, and current state of the topic."),
            ("Recent Developments", "The latest breakthroughs and news, including key research findings published this year."),
            ("Practical Applications", "Real-world use cases and practical applications across multiple industries."),
            ("Expert Analysis", "Leading experts weigh in with analysis, predictions, and recommendations."),
            ("Future Outlook", "Emerging trends and what to expect in the coming years as the field evolves."),
            ("Technical Deep Dive", "An in-depth technical exploration of the underlying mechanisms and architectures."),
            ("Comparative Study", "A comparative analysis examining different approaches, trade-offs, and benchmarks."),
            ("Getting Started Guide", "A beginner-friendly guide with step-by-step instructions and best practices."),
            ("Community and Ecosystem", "The community landscape, major contributors, open-source projects, and ecosystem tools."),
            ("Challenges and Limitations", "Key challenges, known limitations, and ongoing debates in the field."),
        };

        for (var i = 0; i < Math.Min(maxResults, topics.Length); i++)
        {
            results.Add(new
            {
                title = $"{query} — {topics[i].Item1}",
                snippet = topics[i].Item2,
                url = $"https://example.com/{Uri.EscapeDataString(query.Replace(' ', '-').ToLowerInvariant())}/{i + 1}",
            });
        }

        return JsonSerializer.Serialize(results, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using System.Text;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capability for the research agent.
/// The agent uses this tool to collect and organize findings during research.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];

    [Description("Saves a research note with a title, content, and the source URL it came from.")]
    public string SaveNote(
        [Description("A short title for the note")] string title,
        [Description("The content or key findings to save")] string content,
        [Description("The source URL where this information was found")] string sourceUrl)
    {
        _notes.Add(new Note(title, content, sourceUrl, DateTime.UtcNow));
        return $"Note saved: \"{title}\" ({_notes.Count} total notes)";
    }

    [Description("Retrieves all saved research notes collected so far.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===");
        for (var i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"\n--- Note {i + 1}: {note.Title} ---");
            sb.AppendLine($"Source: {note.SourceUrl}");
            sb.AppendLine(note.Content);
        }

        return sb.ToString();
    }

    [Description("Searches saved notes for a keyword and returns matching notes.")]
    public string SearchNotes(
        [Description("The keyword to search for in note titles and content")] string keyword)
    {
        var matches = _notes
            .Where(n => n.Title.Contains(keyword, StringComparison.OrdinalIgnoreCase) ||
                        n.Content.Contains(keyword, StringComparison.OrdinalIgnoreCase))
            .ToList();

        if (matches.Count == 0)
        {
            return $"No notes found matching \"{keyword}\".";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"Found {matches.Count} note(s) matching \"{keyword}\":");
        foreach (var note in matches)
        {
            sb.AppendLine($"\n--- {note.Title} ---");
            sb.AppendLine($"Source: {note.SourceUrl}");
            sb.AppendLine(note.Content);
        }

        return sb.ToString();
    }

    private sealed record Note(string Title, string Content, string SourceUrl, DateTime SavedAt);
}

