using System.ComponentModel;
using System.Text;

namespace ResearchAgent;

/// <summary>
/// Provides note-taking capability for the research agent.
/// The agent uses this tool to collect and organize findings during research.
/// </summary>
public sealed class NoteTakingTool
{
    private readonly List<Note> _notes = [];

    [Description("Saves a research note with a title, content, and the source URL it came from.")]
    public string SaveNote(
        [Description("A short title for the note")] string title,
        [Description("The content or key findings to save")] string content,
        [Description("The source URL where this information was found")] string sourceUrl)
    {
        _notes.Add(new Note(title, content, sourceUrl, DateTime.UtcNow));
        return $"Note saved: \"{title}\" ({_notes.Count} total notes)";
    }

    [Description("Retrieves all saved research notes collected so far.")]
    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===");
        for (var i = 0; i < _notes.Count; i++)
        {
            var note = _notes[i];
            sb.AppendLine($"\n--- Note {i + 1}: {note.Title} ---");
            sb.AppendLine($"Source: {note.SourceUrl}");
            sb.AppendLine(note.Content);
        }

        return sb.ToString();
    }

    [Description("Searches saved notes for a keyword and returns matching notes.")]
    public string SearchNotes(
        [Description("The keyword to search for in note titles and content")] string keyword)
    {
        var matches = _notes
            .Where(n => n.Title.Contains(keyword, StringComparison.OrdinalIgnoreCase) ||
                        n.Content.Contains(keyword, StringComparison.OrdinalIgnoreCase))
            .ToList();

        if (matches.Count == 0)
        {
            return $"No notes found matching \"{keyword}\".";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"Found {matches.Count} note(s) matching \"{keyword}\":");
        foreach (var note in matches)
        {
            sb.AppendLine($"\n--- {note.Title} ---");
            sb.AppendLine($"Source: {note.SourceUrl}");
            sb.AppendLine(note.Content);
        }

        return sb.ToString();
    }

    private sealed record Note(string Title, string Content, string SourceUrl, DateTime SavedAt);
}

