using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using ResearchAgent;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable. " +
        "Optionally set BING_API_KEY for live web search.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- Build the chat client via MEAI abstraction ---
IChatClient chatClient = new OpenAI.OpenAIClient(apiKey)
    .GetChatClient(modelId)
    .AsIChatClient();

// --- Create tool instances ---
using var httpClient = new HttpClient();
var webSearch = new WebSearchTool(httpClient);
var noteTaking = new NoteTakingTool();

// --- Register tools with explicit schemas ---
var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearch.SearchWebAsync),
    AIFunctionFactory.Create(noteTaking.SaveNote),
    AIFunctionFactory.Create(noteTaking.GetAllNotes),
    AIFunctionFactory.Create(noteTaking.SearchNotes),
};

// --- Build the agent ---
const string instructions = """
    You are a research agent. Your job is to research a topic thoroughly by:

    1. SEARCH: Use the SearchWebAsync tool to find relevant information. Run multiple
       searches with different queries to cover the topic from various angles.
    2. TAKE NOTES: For each useful result, use SaveNote to record key findings with
       the source URL. Be selective — save only substantive information.
    3. REVIEW: Use GetAllNotes to review what you have collected so far. Identify gaps
       in your research and search for more information if needed.
    4. SUMMARIZE: Once you have gathered enough information (at least 3-5 notes),
       produce a well-structured summary with:
       - An executive overview (2-3 sentences)
       - Key findings organized by theme
       - Sources cited with URLs

    Always search before summarizing. Never fabricate information — only summarize
    what you found through your tools.
    """;

var agent = new ChatClientAgent(
    chatClient,
    instructions: instructions,
    name: "ResearchAgent",
    description: "Researches topics using web search and note-taking tools",
    tools: tools);

// --- Get the research topic ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        AI Research Agent                 ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

string topic;
if (args.Length > 0)
{
    topic = string.Join(' ', args);
}
else
{
    Console.Write("Enter a research topic: ");
    topic = Console.ReadLine()?.Trim() ?? string.Empty;
}

if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("Error: No topic provided.");
    return 1;
}

Console.WriteLine($"\nResearching: {topic}\n");

// --- Run the agent ---
var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var session = await agent.CreateSessionAsync();

await foreach (var message in agent.RunStreamingAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session,
    runOptions))
{
    if (message.Role == ChatRole.Assistant)
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine();
return 0;

